#'
#' Summarize the drug effect across concentrations
#'
#'This function summarizes the normalized drug effect (viability) across multiple
#'concentrations into a single value. The summary is based on the normalized
#'viability values, which require plate normalization as a prerequisite.
#'If the viability values have been corrected for incubation/edge effect, the
#'function will normalize both the corrected and uncorrected values and add
#'a suffix, ‘.cor’, to the columns with the summary values.
#'
#' @param screenData the data frame containing screening data generated by
#' \code{readScreen()} function
#' @param method a character string or a vector of character strings specifying
#' the method to summarize the drug effects.
#'  There are currently four methods available: average, AUC, DSS, and IC50.
#'  The average method calculates the average drug effect across all concentrations.
#'  The AUC method calculates the normalized area under the dose-response curve
#'  using the trapezoidal method.
#'  The IC50 method first fits a robust four-parameter log-logistic model using
#'  the dr4pl package. Then, it summarizes the drug effect using the four
#'  parameters (upper limit, lower limit, slope, and IC50/EC50) and area under
#'  the sigmoid curve.You can use multiple methods simultaneously by specifying
#'  a vector of method names.
#'@param minConc, lower bound of concentrations for the integration of area
#'under curve. Used for method = "IC50". See \code{sumIC50()}.
#'@param maxConc, upper bound of concentrations for the integration of area
#'under curve. Used for method = "IC50". See \code{sumIC50()}.
#' @param dssType, type or types of DSS score to calculate. Options are
#' "DSS1", "DSS2", "DSS3", or "all". Multiple types may be supplied. A single
#' type is returned in the historical \code{DSS} column; multiple types are
#' returned in columns named after each type. (default is "DSS2")
#' @param dssThreshold, threshold for DSS score calculation provided as a percentage. Should be a numeric value between 0 and 100. (default is 10)
#' @export
#' @import  tidyr
#' @importFrom dr4pl dr4pl
#'
#' @return The following columns will be added to the input data frame depending
#' on the user-specified summarizing methods:
#'
#' If \code{method = 'average'},
#'
#' \item{meanViab}{the averaged viability across all concentrations for a certain drug}
#'
#' If \code{method = 'AUC'}
#'
#' \item{AUC}{the area under the dose-response curve calculated by using the
#' trapezoidal rule.}
#'
#' If \code{method = 'IC50'}
#'
#' \item{UpperLimit}{the upper limit of the fitted logistic model}
#' \item{IC50}{the half maximal inhibitory concentration (IC50), or the half
#' maximal effective concentration (EC50), depends on the type of input data}
#' \item{Slope}{the slope of the fitted logistic model}
#' \item{lowerLimit}{the upper limit of the fitted logistic model}
#' \item{AUC}{the area under the fitted sigmoid doese-response curve}
#'
#' If the logistic model can not be fitted for a certain drug, the above four
#' values will be set to NA.
#' 
#' If \code{method = 'DSS'}
#' 
#' \item{DSS}{the drug sensitivity score calculated based on the viability
#' and concentration values. The DSS1 score is a normalized version of the
#' AUC that will only consider the drug effect above a user-defined threshold.
#' The DSS score is calculated using the \code{calcDSS()} function. The DSS2
#' score is further normalized by comparing the DSS1 score to the maximum
#' possible AUC for the given concentration range. The DSS3 score is a
#' modified version of the DSS2 score that takes into account the slope
#' of the dose-response curve.}
#' 
#'
#'
#' If a column that contains the edge/incubation effect corrected viability
#' values is present in the input data frame,
#' the above columns with a suffix \code{.cor}, which represent the summarized
#' values based on edge/incubation corrected viabilities, will also be added to
#' the input data frame.
#'
#' @examples
#' data(screenData_normalized)
#' screenData <- summariseScreen(screenData_normalized)
#'
#' # Please see the vignette for more information

summariseScreen <- function(screenData,
                            method = c("average", "AUC", "IC50", "DSS"),
                            minConc = 0, maxConc = 15,
                            dssType = "DSS2", dssThreshold = 10) {

  # check if necessary columns are present in the input data
  if (!all(c("drug", "concentration", "sampleID", "wellType", "normVal") %in% colnames(screenData))) {
    stop("screenData must contain: sampleID, drug, concentration, wellType, and normVal.")
  }

  # Ensure method name is valid
  valid_methods <- c("average", "AUC", "IC50", "DSS")

  if (!is.character(method) ||
      length(method) == 0 ||
      anyNA(method) ||
      any(!method %in% valid_methods)) {
    stop("method must contain one or more valid method names.")
  }
  
  valid_dss_types <- c("DSS1", "DSS2", "DSS3")
  if (!is.character(dssType) || length(dssType) == 0 || anyNA(dssType)) {
    stop("Invalid DSS type. Choose one or more of 'DSS1', 'DSS2', 'DSS3', or 'all'.")
  }
  if ("all" %in% dssType) {
    dss_types <- valid_dss_types
  } else {
    dss_types <- unique(dssType)
  }
  if (any(!dss_types %in% valid_dss_types)) {
    stop("Invalid DSS type. Choose one or more of 'DSS1', 'DSS2', 'DSS3', or 'all'.")
  }

  if (length(dssThreshold) != 1 ||
      !is.numeric(dssThreshold) ||
      !is.finite(dssThreshold) ||
      dssThreshold < 0 ||
      dssThreshold >= 100) {
    stop("dssThreshold must be one finite numeric value in [0, 100).")
  }


  # Check if the 'normVal.cor' column is present
  ifCor <- "normVal.cor" %in% colnames(screenData)

  # Only summarize the non-control wells
  subData <- screenData[screenData$wellType %in% "sample", ]

  # get the mean by concentration
  # drug combinations or single drug
  if (ifCor) {
    subData <- subData %>%
      group_by(sampleID, drug, concentration) %>%
      summarise(viab = mean(normVal, na.rm = TRUE),
                viab.cor = mean(normVal.cor, na.rm = TRUE)) %>%
      ungroup()
  } else {
    subData <- subData %>%
      group_by(sampleID, drug, concentration) %>%
      summarise(viab = mean(normVal, na.rm = TRUE)) %>%
      ungroup()
  }

  # summarize average, IC50 and AUC
  # drug combinations or single drug
  grouped_subData <- subData %>%
    group_by(sampleID, drug)

  # "average" in method
  if ("average" %in% method) {
    # if normVal.cor is available
    if (ifCor) {
      sumTab <- grouped_subData %>%
        dplyr::summarise(meanViab = mean(viab, na.rm = TRUE),
                         meanViab.cor = mean(viab.cor, na.rm = TRUE)) %>%
        ungroup()
    } else {
      sumTab <- grouped_subData %>%
        dplyr::summarise(meanViab = mean(viab, na.rm = TRUE)) %>%
        ungroup()
    }

    # Remove existing 'meanViab' column if it already exists in the input data
    if ("meanViab" %in% colnames(screenData))
      screenData[["meanViab"]] <- NULL

    if ("meanViab.cor" %in% colnames(screenData))
      screenData[["meanViab.cor"]] <- NULL

    # Join the summarized data back to the original data
    screenData <- left_join(screenData, sumTab, by = c("sampleID", "drug"))
  }

  # "AUC" in method
  if ("AUC" %in% method) {
    if (ifCor) {
      sumTab <- grouped_subData %>%
        dplyr::summarise(AUC = calcAUC(viab, concentration),
                         AUC.cor = calcAUC(viab.cor, concentration)) %>%
        ungroup()
    } else {
      sumTab <- grouped_subData %>%
        dplyr::summarise(AUC = calcAUC(viab, concentration)) %>%
        ungroup()
    }

    # Remove existing 'AUC' and 'AUC.cor' column if it already exists in the input data
    if ("AUC" %in% colnames(screenData)){
      screenData[["AUC"]] <- NULL
    }

    if ("AUC.cor" %in% colnames(screenData)){
      screenData[["AUC.cor"]] <- NULL
    }

    screenData <- left_join(screenData, sumTab, by = c("sampleID", "drug"))
  }

  # "IC50" in method
  if ("IC50" %in% method) {
    # Group and nest the data for IC50 calculation
    sumTab <- grouped_subData %>%
      tidyr::nest() %>%
      dplyr::mutate(
        model = purrr::map(data, ~ sumIC50(viab ~ concentration,
                                           data = .,
                                           minConc = minConc,
                                           maxConc = maxConc))) %>%
      tidyr::unnest("model") %>%
      ungroup()

    sumTab$data <- NULL

    if (ifCor) {
      sumTab.cor <- grouped_subData %>%
        tidyr::nest() %>%
        dplyr::mutate(
          model = purrr::map(data, ~ sumIC50(viab.cor ~ concentration,
                                             data = .,
                                             minConc = minConc,
                                             maxConc = maxConc))) %>%
        tidyr::unnest("model") %>%
        ungroup()

      sumTab.cor$data <- NULL
      newColName <- colnames(sumTab.cor)
      newColName[!newColName %in% c("sampleID", "drug")] <-
        paste0(newColName[!newColName %in% c("sampleID", "drug")], ".cor")

      colnames(sumTab.cor) <- newColName
      sumTab <- left_join(sumTab, sumTab.cor, by = c("sampleID", "drug"))
    }

    # remove existing columns
    for (colN in c("UpperLimit", "IC50", "Slope", "LowerLimit", "AUC")) {
      if (colN %in% colnames(screenData))
        screenData[[colN]] <- NULL
    }

    for (colN in c("UpperLimit.cor", "IC50.cor", "Slope.cor", "LowerLimit.cor",
                   "AUC.cor")) {
      if (colN %in% colnames(screenData))
        screenData[[colN]] <- NULL
    }

    # Join the summarized IC50 data back to the original data
    screenData <- left_join(screenData, sumTab, by = c("sampleID", "drug"))
  }

    # Add section for calculating DSS score. FH
  if ("DSS" %in% method) {
      dss_columns <- if (length(dss_types) == 1) "DSS" else dss_types
      dss_tables <- lapply(seq_along(dss_types), function(i) {
        grouped_subData %>%
          dplyr::summarise(!!dss_columns[i] :=
                             calcDSS(viab, concentration,
                                     dssType = dss_types[i],
                                     threshold = dssThreshold)) %>%
        ungroup()
      })
      sumTab <- Reduce(function(x, y) left_join(x, y,
                                                 by = c("sampleID", "drug")),
                       dss_tables)

      if (ifCor) {
        dss_cor_tables <- lapply(seq_along(dss_types), function(i) {
          grouped_subData %>%
            dplyr::summarise(!!paste0(dss_columns[i], ".cor") :=
                               calcDSS(viab.cor, concentration,
                                       dssType = dss_types[i],
                                       threshold = dssThreshold)) %>%
            ungroup()
        })
        sumTab.cor <- Reduce(function(x, y) left_join(x, y,
                                                       by = c("sampleID", "drug")),
                             dss_cor_tables)
        sumTab <- left_join(sumTab, sumTab.cor, by = c("sampleID", "drug"))
      }

      for (colN in c(dss_columns, paste0(dss_columns, ".cor"))) {
        if (colN %in% colnames(screenData))
          screenData[[colN]] <- NULL
      }

      screenData <- left_join(screenData, sumTab, by = c("sampleID", "drug"))
    }


  return(screenData)
}




